        this.city = city;
        this.country = country;
        this.timezone = timezone;
        this.region = region;
        this.geoNameId = Long.valueOf(geoNameId);
        this.latitude = Double.valueOf(latitude);
        this.longitude = Double.valueOf(longitude);
    }

